  async function downloadGame(){const loading=window.SengokuLoading?.begin('ダウンロードを開いています…');try{const a=document.createElement('a');a.href='https://github.com/uni-tadayasu/sengoku-taisen/archive/refs/heads/main.zip';a.download='sengoku-taisen-download.zip';a.rel='noopener';document.body.append(a);a.click();a.remove();toast('ZIPのダウンロードを開きました。すべて展開して index.html をブラウザで開いてください。');}catch(_){toast('ダウンロードを開けませんでした。GitHubの Code → Download ZIP も利用できます。',true);}finally{if(loading)await window.SengokuLoading.end(loading);}}
