  let music=null;
  function ensureAudio(){if(!music)music=new SengokuMusic({volume:settings.volume});return music;}
  function sceneTrack(scene){const tracks=window.SENGOKU_MUSIC_TRACKS||[];if(settings.musicMode==='manual'&&tracks.some(t=>t.id===settings.track))return settings.track;const match=tracks.filter(t=>t.scene===(scene||({town:'town',facilities:'town',map:'world',officers:'officers',army:'army',research:'research',council:'chronicle'})[currentView]||'town'));return (match[Math.floor(state().turn/3)%Math.max(1,match.length)]||tracks[0])?.id;}
  function syncMusic(scene){if(!settings.sound)return;try{const player=ensureAudio(),id=sceneTrack(scene);if(id&&id!==player.currentId)player.play(id).catch(()=>{});}catch(_){} }
